#pragma once
// NetTypes - fixed-size vector / matrix for small networks on the M4. No heap, sizes checked by the compiler:
//   Vec<4> x;  Mat<5, 4> W;   W * x -> Vec<5>,   a + b,  a - b,  k * a,  dot(a, b),  tanh(a),  withOne(a) -> Vec<N+1>
// Written by hand; the weights (ResidualNetWeights.h) are generated by collectedData/NeuroFligh/makeHeader.py.

#include <math.h>
#include <stddef.h>

namespace nn {

template <size_t N>
struct Vec {
  float v[N];

  float&       operator[](size_t i)       { return v[i]; }
  const float& operator[](size_t i) const { return v[i]; }
  static constexpr size_t size() { return N; }

  Vec& operator+=(const Vec& o) { for (size_t i = 0; i < N; i++) v[i] += o.v[i]; return *this; }
  Vec& operator-=(const Vec& o) { for (size_t i = 0; i < N; i++) v[i] -= o.v[i]; return *this; }
  Vec& operator*=(float k)      { for (size_t i = 0; i < N; i++) v[i] *= k;      return *this; }
};

template <size_t R, size_t C>             // R rows (outputs) x C columns (inputs), as numpy's W
struct Mat {
  float m[R][C];

  float&       operator()(size_t r, size_t c)       { return m[r][c]; }
  const float& operator()(size_t r, size_t c) const { return m[r][c]; }
};

template <size_t N> Vec<N> operator+(Vec<N> a, const Vec<N>& b) { return a += b; }
template <size_t N> Vec<N> operator-(Vec<N> a, const Vec<N>& b) { return a -= b; }
template <size_t N> Vec<N> operator*(Vec<N> a, float k)         { return a *= k; }
template <size_t N> Vec<N> operator*(float k, Vec<N> a)         { return a *= k; }

template <size_t R, size_t C>
Vec<R> operator*(const Mat<R, C>& W, const Vec<C>& x) {   // W x
  Vec<R> y;
  for (size_t r = 0; r < R; r++) {
    float s = 0.0f;
    for (size_t c = 0; c < C; c++) s += W.m[r][c] * x.v[c];
    y.v[r] = s;
  }
  return y;
}

template <size_t N>
float dot(const Vec<N>& a, const Vec<N>& b) {
  float s = 0.0f;
  for (size_t i = 0; i < N; i++) s += a.v[i] * b.v[i];
  return s;
}

template <size_t N>
Vec<N> tanh(Vec<N> a) {                   // element by element
  for (size_t i = 0; i < N; i++) a.v[i] = tanhf(a.v[i]);
  return a;
}

template <size_t N>
Vec<N> normalise(Vec<N> x, const Vec<N>& mean, const Vec<N>& std) {   // (x - mean) / std, element by element
  for (size_t i = 0; i < N; i++) x.v[i] = (x.v[i] - mean.v[i]) / std.v[i];
  return x;
}

template <size_t N>
Vec<N + 1> withOne(const Vec<N>& a) {     // [a, 1]: the constant feature
  Vec<N + 1> y;
  for (size_t i = 0; i < N; i++) y.v[i] = a.v[i];
  y.v[N] = 1.0f;
  return y;
}

}  // namespace nn
